/* Lot 112: font-size with ex, ch, lh and rlh; ex and ch of the engine's font (generated by scripts/lot112_gen.py; expectations from scripts/lot112_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[2048];
static char g_o[512];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    TEST_ASSERT_EQUAL(5, g_d.nnodes);
}

/* the font sizes of html, #o and #i (px thousandths) */
static const char *fs3(void) {
    snprintf(g_o, sizeof(g_o), "%d %d %d", g_d.fs[0], g_d.fs[3], g_d.fs[4]);
    return g_o;
}

/* the line heights of body, #o and #i (px thousandths + 1, 0 normal) */
static const char *lh3(void) {
    snprintf(g_o, sizeof(g_o), "%d %d %d", g_d.lh[2], g_d.lh[3], g_d.lh[4]);
    return g_o;
}

/* the height (px) in the style passed for the element with that id,
 * -1 when it has none */
static int height_of(const char *id) {
    int i, v = -1;
    const char *h;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    h = strstr(g_o, ";height:");
    if (!h) h = strstr(g_o, "\"height:");
    if (h) sscanf(h + 8, "%d", &v);
    return v;
}

static void test_l112_font_0(void) {
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: 4.5ch } html { font-size: 12px } #o { line-height: 4ex; overflow: auto; height: 10ch } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("12000 12000 36000", fs3());
    TEST_ASSERT_EQUAL_STRING("0 20001 20001", lh3());
    TEST_ASSERT_EQUAL(80, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: 20px; overflow: auto; height: calc(2ex + 1ch) } #i { font-size: 0.75lh; line-height: 2rlh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 20000 9375", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 20001", lh3());
    TEST_ASSERT_EQUAL(22, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { overflow: auto; height: calc(2ex + 1ch) } #i { font-size: -1ex } body { font-size: 0.5ex } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 2500 2500", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
    TEST_ASSERT_EQUAL(18, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { overflow: auto; height: 3ch } #i { font-size: 3ch } body { font-size: 3ch; line-height: 20px } html { font-size: 1.5ch } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("12000 24000 36000", fs3());
    TEST_ASSERT_EQUAL_STRING("20001 20001 20001", lh3());
    TEST_ASSERT_EQUAL(36, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: clamp(8px, 2ex, 40px) } html { line-height: 1.5 } #o { overflow: auto; height: calc(1lh + 2ex) } body { font-size: calc(1lh + 1ch); line-height: calc(2ex + 1ch) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 32000 20000", fs3());
    TEST_ASSERT_EQUAL_STRING("36001 36001 36001", lh3());
    TEST_ASSERT_EQUAL(56, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: 24px; overflow: auto; height: 2.5ex } #i { font-size: 4.5ch; line-height: 1.5 } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 24000 54000", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 81001", lh3());
    TEST_ASSERT_EQUAL(20, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: 2lh; line-height: 150%; overflow: auto; height: calc(2ex + 1ch) } body { font-size: 1.5lh } #i { font-size: calc(50% + 1ex); line-height: 4ex } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 18750 15375", fs3());
    TEST_ASSERT_EQUAL_STRING("0 28126 20001", lh3());
    TEST_ASSERT_EQUAL(22, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: 0.5ex; line-height: 2rlh } #o { font-size: clamp(8px, 2ex, 40px); overflow: auto; height: max(3ex, 2ch) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 10000 2500", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 20001", lh3());
    TEST_ASSERT_EQUAL(16, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: calc(2ch - 2px); line-height: normal; overflow: auto; height: max(3ex, 2ch) } #i { font-size: 40px; line-height: 2rlh } body { font-size: 1.5em } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 22000 40000", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 20001", lh3());
    TEST_ASSERT_EQUAL(24, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #i { font-size: 3ch } #o { overflow: auto; height: 2.5ex } html { line-height: 20px } body { font-size: 20px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 20000 30000", fs3());
    TEST_ASSERT_EQUAL_STRING("20001 20001 20001", lh3());
    TEST_ASSERT_EQUAL(15, height_of("o"));
}

