    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: -1ex; line-height: 3ch; overflow: auto; height: calc(1lh + 2ex) } html { font-size: 20px; line-height: 1.25 } #i { font-size: calc(100% - 1ch) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("20000 20000 10000", fs3());
