    TEST_ASSERT_EQUAL(42, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } body { font-size: 24px } html { line-height: 2ex } #o { font-size: 0.5ex; overflow: auto; height: 3ch } #i { font-size: calc(1lh + 1ch) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 4000 18000", fs3());
