    TEST_ASSERT_EQUAL_STRING("16000 12000 12000", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
    TEST_ASSERT_EQUAL(20, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } body { font-size: 2lh } #o { font-size: calc(1lh + 1ch); line-height: 2ex; overflow: auto; height: 6ch } html { line-height: 1.25 } #i { font-size: 2ex } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 70000 40000", fs3());
    TEST_ASSERT_EQUAL_STRING("50001 40001 40001", lh3());
    TEST_ASSERT_EQUAL(192, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: 24px; overflow: auto; height: max(3ex, 2ch) } html { font-size: 20px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("20000 24000 24000", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
    TEST_ASSERT_EQUAL(24, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } #o { font-size: calc(50% + 1ex); overflow: auto; height: 10ch } html { line-height: 4ex } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("16000 13000 13000", fs3());
