    TEST_ASSERT_EQUAL(80, height_of("o"));
    prep("@keyframes k { from { color: #000000 } to { color: #ffffff } } html { font-size: 3ch } #i { font-size: 2lh } #o { font-size: 2rlh; overflow: auto; height: calc(1lh + 2ex) } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }");
    TEST_ASSERT_EQUAL_STRING("24000 30000 37500", fs3());
    TEST_ASSERT_EQUAL_STRING("0 0 0", lh3());
